CREATE TABLE IF NOT EXISTS log(x, y);
CREATE TRIGGER IF NOT EXISTS gt0 AFTER UPDATE ON t0 BEGIN INSERT INTO log VALUES('t0', NEW.id); END;
INSERT INTO t0(id) VALUES(133);
UPDATE t0 SET id = id + 1000 WHERE id < 3;
DELETE FROM t0 WHERE id > 1000;
SELECT * FROM log ORDER BY rowid;
CREATE VIEW IF NOT EXISTS vt0 AS SELECT a.id, b.id AS bid FROM t0 a LEFT JOIN t1 b ON a.id = b.id;
SELECT * FROM vt0 ORDER BY id LIMIT 10;
SELECT id, c3, abs(typeof(coalesce(NULL, id))) FROM t0 ORDER BY id, c0 DESC, c1, c2, c3, c4;
